import type { MaterialKind, Series, SeriesKey } from "./catalogue";

/**
 * The library manifest: what the build produced and where it is.
 *
 * Generated by `scripts/library/build.ts` and stored in private Blob storage
 * beside every file it points to. The app reads it at runtime; nothing in it
 * is committed, because it carries the owner's own wording.
 *
 * Every file is content-addressed (`<sha256>.<ext>`), so an unchanged file
 * keeps its name across builds and only what changed is uploaded again.
 */

/** `<hex>.<ext>`, the file's name in the `library/assets/` folder. */
export type AssetName = string;

export type FileRef = { asset: AssetName; name: string; bytes: number };

export type SlideRef = {
  image: AssetName;
  thumb: AssetName;
  /** The slide's heading, where one can be found. */
  title: string | null;
  /** The speaker notes for this slide, where the deck has them. */
  notes: string | null;
};

export type PageRef = { image: AssetName; thumb: AssetName };

export type DocSection = { id: string; title: string; level: number };

type MaterialBase = {
  id: string;
  kind: MaterialKind;
  title: string;
  subtitle: string | null;
  /** The file as the owner sent it. */
  original: FileRef;
  /** A PDF for printing and sharing, made from the same rendering. */
  pdf: FileRef;
  pageCount: number;
  cover: AssetName;
  words: number;
};

/** A Word document, shown as a web page. */
export type DocumentMaterial = MaterialBase & {
  format: "document";
  html: AssetName;
  sections: DocSection[];
  header: string | null;
  footer: string | null;
  /** Width of the printed text column, in inches. */
  columnInches: number;
};

/** A PowerPoint deck, shown slide by slide. */
export type SlidesMaterial = MaterialBase & {
  format: "slides";
  slides: SlideRef[];
  /** Width ÷ height. */
  aspect: number;
};

/** A PDF, shown page by page. */
export type PagesMaterial = MaterialBase & {
  format: "pages";
  pages: PageRef[];
  aspect: number;
};

export type LibraryMaterial = DocumentMaterial | SlidesMaterial | PagesMaterial;

export type LibraryCollection = {
  slug: string;
  series: SeriesKey;
  number: number | null;
  /** "Worksheet 5", or null. */
  label: string | null;
  title: string;
  aliases: string[];
  /** The resource's own statement of its aim, taken from its guides. */
  summary: string | null;
  cover: AssetName;
  materials: LibraryMaterial[];
  onlineWorksheetKey: string | null;
};

export type LibraryManifest = {
  version: 1;
  builtAt: string;
  series: Series[];
  collections: LibraryCollection[];
  /** The search index, a `SearchIndex` JSON file. */
  search: AssetName;
};

/**
 * One searchable piece of text.
 *
 * `m` is null for the collection's own details; `at` is null for a
 * material's details, otherwise where in it the text is: a section id
 * (`s3`), a slide (`slide-4`) or a page (`page-2`).
 */
export type SearchEntry = {
  c: string;
  m: string | null;
  at: string | null;
  label: string | null;
  text: string;
};

export type SearchIndex = { version: 1; entries: SearchEntry[] };
